import json, os, sys

BASE = "/Users/kristinarash/Library/Caches/sportsci-batch-97"
HELP = os.path.join(BASE, "helpers", "g8")
ids = ["Q57", "Q58", "Q59", "Q60", "Q61", "Q62", "Q63", "Q64"]

inputs = json.load(open(os.path.join(BASE, "inputs.json"), encoding="utf-8"))
src = {d["id"]: d["sourceFile"] for d in inputs}
tax = json.load(open(os.path.join(BASE, "taxonomy.json"), encoding="utf-8"))

problems = []
written = []
for pid in ids:
    c = json.load(open(os.path.join(HELP, pid + ".in.json"), encoding="utf-8"))
    out = {"id": c["id"], "sourceFile": src[pid]}
    for k, v in c.items():
        if k == "id":
            continue
        out[k] = v
    dec = out["decision"]
    if dec == "INCLUDE" or dec == "DEGRADED":
        if out["studyDesign"] not in tax["studyDesigns"]:
            problems.append((pid, "bad studyDesign"))
        if out["primaryDomain"] not in tax["domains"]:
            problems.append((pid, "bad primaryDomain"))
        if out["primaryDomain"] not in out["domains"]:
            problems.append((pid, "primaryDomain not in domains"))
        for d in out["domains"]:
            if d not in tax["domains"]:
                problems.append((pid, "bad domain " + d))
        for a in out["audiences"]:
            if a not in tax["audiences"]:
                problems.append((pid, "bad audience " + a))
        for s in out["sports"]:
            if s not in tax["sports"]:
                problems.append((pid, "bad sport " + s))
        for p in out["populations"]:
            if p not in tax["populations"]:
                problems.append((pid, "bad population " + p))
        if dec == "INCLUDE" and not out["paper"]["doi"].startswith("10."):
            problems.append((pid, "INCLUDE without DOI"))
    path = os.path.join(BASE, "drafts", pid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=1)
        f.write("\n")
    written.append((pid, dec))

print("written:", written)
print("problems:", problems if problems else "none")

